package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueLevelOptions;

class LevelVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property level of observed issue ")
  void test_level_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> LevelVO.tryFrom("_WARNING_"));
    Assertions.assertEquals(ObservedIssueLevelOptions.WARNING,
        LevelVO.tryFrom("WARNING").getLevel());
    Assertions.assertThrows(ConstraintException.class, () -> LevelVO.tryFrom(null));
    Assertions.assertEquals(ObservedIssueLevelOptions.WARNING,
        LevelVO.from(ObservedIssueLevelOptions.WARNING).getLevel());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LevelVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedIssueLevelOptions.WARNING + "]",
        LevelVO.from(ObservedIssueLevelOptions.WARNING).toString());
  }
}
